{"file_text": "<div class="message-area">
    @if (CurrentChannel is not null)
    {
        <div class="channel-header">
            <h2># @CurrentChannel.Name</h2>
            <p>@CurrentChannel.Description</p>
        </div>

        <div class="message-list">
            @if (HasMoreMessages)
            {
                <button class="load-more-btn" @onclick="OnLoadMore" disabled="@IsLoading">
                    @(IsLoading ? "Loading…" : "↑ Load older messages")
                </button>
            }

            @foreach (var msg in Messages)
            {
                <MessageBubble Message="msg"
                               ThreadSummary="@GetThreadSummary(msg.Id)"
                               OnReply="OnOpenThread"
                               OnReact="OnReact"
                               OnOpenThread="OnOpenThread" />
            }
        </div>

        <MessageInput Placeholder="@($"Message #{CurrentChannel.Name}")"
                      ButtonText="Send"
                      OnSubmit="OnSendMessage" />
    }
    else
    {
        <div class="empty-state">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter] public Channel? CurrentChannel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public bool IsLoading { get; set; }
    [Parameter] public bool HasMoreMessages { get; set; }

    private ThreadSummary? GetThreadSummary(int messageId)
    {
        ThreadSummaries.TryGetValue(messageId, out var summary);
        return summary;
    }
}
", "path": "/tmp/sv-e4947d84301f40f78536b794477077ae/Components/Chat/MessageArea.razor"}

