    margin: 0.5rem 0.75rem;
    border-radius: 0 6px 6px 0;
    flex-shrink: 0;
}

.quote-author {
    font-weight: 700;
    font-size: 0.8rem;
    color: #333;
}

.quote-content {
    margin: 0.2rem 0 0;
    font-size: 0.85rem;
    color: #555;
    white-space: pre-wrap;
    word-break: break-word;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.25rem 0;
}

.no-replies {
    text-align: center;
    color: #999;
    font-size: 0.85rem;
    padding: 1.5rem;
}
