.thread-panel {
    width: 25%;
    min-width: 260px;
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    background: #fafbfc;
    border-left: 1px solid #e0e0e0;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #888;
    border-radius: 4px;
    padding: 0.15rem 0.4rem;
}

.close-btn:hover {
    background: #eee;
    color: #333;
}

.thread-root-quote {
    padding: 0.6rem 1rem;
    border-bottom: 1px solid #e0e0e0;
    background: #f0f2f5;
    border-left: 3px solid #4a76a8;
    margin: 0.5rem 0.75rem;
    border-radius: 0 6px 6px 0;
    flex-shrink: 0;
