arguments.file_text:
.chat-layout {
    height: 100vh;
    width: 100vw;
    overflow: hidden;
    display: flex;
}

@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<ChannelSidebar Channels="channels"
                SelectedChannelId="selectedChannel?.Id"
                OnChannelSelected="SelectChannel" />

<MessageArea CurrentChannel="selectedChannel"
             Messages="messages"
             ThreadSummaries="threadSummaries"
             OnSendMessage="SendMessage"
             OnOpenThread="OpenThread"
             OnReact="AddReaction"
             OnLoadMore="LoadMoreMessages"
             IsLoading="isLoading"
             HasMoreMessages="hasMoreMessages" />

<ThreadPanel RootMessage="openThreadRoot"
             ThreadMessages="threadMessages"
             OnClose="CloseThread"
             OnSendReply="SendThreadReply"
             OnReact="AddReaction" />

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private Dictionary<int, ThreadSummary> threadSummaries = [];

    private Message? openThreadRoot;
    private List<Message> threadMessages = [];

    private bool isLoading;
    private bool hasMoreMessages = true;
    private const int PageSize = 50;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannel = channel;
        messages = [];
        threadSummaries = [];
        hasMoreMessages = true;
        CloseThread();

        await LoadMessages();
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Clear unread badge locally
        var idx = channels.FindIndex(c => c.Id == channel.Id);
        if (idx >= 0)
        {
            channels[idx] = channel with { UnreadCount = 0 };
        }
    }

    private async Task LoadMessages()
    {
        if (selectedChannel is null || isLoading) return;

        isLoading = true;

        try
        {
            var loaded = await ChatService.GetMessagesAsync(
                selectedChannel.Id, messages.Count, PageSize);

            if (loaded.Count < PageSize)
                hasMoreMessages = false;

            // Separate root messages from replies; build thread summaries
            var roots = new List<Message>();
            foreach (var msg in loaded)
            {
                if (msg.ReplyToId is null)
                {
                    roots.Add(msg);
                }
                else
                {
                    var rootId = msg.ReplyToId.Value;
                    if (threadSummaries.TryGetValue(rootId, out var existing))
                    {
                        threadSummaries[rootId] = existing with
                        {
                            ReplyCount = existing.ReplyCount + 1,
                            LastReplyAt = msg.SentAt > existing.LastReplyAt
                                ? msg.SentAt : existing.LastReplyAt
                        };
                    }
                    else
                    {
                        threadSummaries[rootId] = new ThreadSummary(rootId, 1, msg.SentAt);
                    }
                }
            }

            // Older messages go on top
            messages.InsertRange(0, roots);
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task LoadMoreMessages() => await LoadMessages();

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;

        var msg = await ChatService.SendMessageAsync(
            selectedChannel.Id, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        openThreadRoot = messages.FirstOrDefault(m => m.Id == messageId);
        if (openThreadRoot is null) return;

        threadMessages = await ChatService.GetThreadAsync(messageId);

        // Update cached thread summary
        if (threadMessages.Count > 0)
        {
            threadSummaries[messageId] = new ThreadSummary(
                messageId,
                threadMessages.Count,
                threadMessages.Max(m => m.SentAt));
        }
    }

    private void CloseThread()
    {
        openThreadRoot = null;
        threadMessages = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannel is null || openThreadRoot is null) return;

        var reply = await ChatService.SendMessageAsync(
            selectedChannel.Id, content, openThreadRoot.Id);
        threadMessages.Add(reply);

        // Update thread summary
        var rootId = openThreadRoot.Id;
        threadSummaries[rootId] = new ThreadSummary(
            rootId, threadMessages.Count, reply.SentAt);
    }

    private async Task AddReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        UpdateReactionLocally(messages, reaction);
        UpdateReactionLocally(threadMessages, reaction);
    }

    private static void UpdateReactionLocally(
        List<Message> list, (int MessageId, string Emoji) reaction)
    {
        var idx = list.FindIndex(m => m.Id == reaction.MessageId);
        if (idx < 0) return;

        var msg = list[idx];
        var reactions = msg.Reactions ?? [];
        var existing = reactions.FirstOrDefault(r => r.Emoji == reaction.Emoji);

        if (existing is not null)
        {
            existing.Users.Add("You");
        }
        else
        {
            reactions.Add(new Reaction(reaction.Emoji, ["You"]));
        }

        list[idx] = msg with { Reactions = reactions };
    }
}

